windowclass.script:
function onInit()
	self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));

	local node = getDatabaseNode();
	if node then
		DB.addHandler(DB.getPath(node, "group"), "onUpdate", onDataUpdate);
		DB.addHandler(DB.getPath(node, "feat"), "onUpdate", onDataUpdate);
		DB.addHandler(DB.getPath(node, "ability"), "onUpdate", onDataUpdate);
		DB.addHandler(DB.getPath(node, "trained"), "onUpdate", onDataUpdate);
		DB.addHandler(DB.getPath(node, "armorcheckpenalty"), "onUpdate", onDataUpdate);
	end
end
function onClose()
	local node = getDatabaseNode();
	if node then
		DB.removeHandler(DB.getPath(node, "group"), "onUpdate", onDataUpdate);
		DB.removeHandler(DB.getPath(node, "feat"), "onUpdate", onDataUpdate);
		DB.removeHandler(DB.getPath(node, "ability"), "onUpdate", onDataUpdate);
		DB.removeHandler(DB.getPath(node, "trained"), "onUpdate", onDataUpdate);
		DB.removeHandler(DB.getPath(node, "armorcheckpenalty"), "onUpdate", onDataUpdate);
	end
end
function onDataUpdate()
	self.updateTypeLabel();
end
function update()
	self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
end
function onLockModeChanged(bReadOnly)
	local tFields = { "ability", "trained", "armorcheckpenalty", "feat", "group", };
	WindowManager.callSafeControlsSetLockMode(self, tFields, bReadOnly);

	self.updateTypeLabel();
	WindowManager.callSafeControlsSetVisible(self, { "type_label", }, bReadOnly);
	WindowManager.callSafeControlsSetVisible(self, tFields, not bReadOnly);

	WindowManager.callSafeControlsSetLockMode(self, { "text", }, bReadOnly);
end
function updateTypeLabel()
	local tLabel = {};

	local sGroup = "";
	if group then
		sGroup = (group.getValue() or ""):lower();
	end
	local bForce = (sGroup == "force") or sGroup:match("force");

	local sAbility = "";
	if ability then
		sAbility = ability.getValue() or "";
	end
	if sAbility ~= "" then
		table.insert(tLabel, sAbility);
	end

	if bForce then
		table.insert(tLabel, "Force Skill");
	end

	if trained and (trained.getValue() or 0) ~= 0 then
		table.insert(tLabel, "Trained only");
	end
	if armorcheckpenalty and (armorcheckpenalty.getValue() or 0) ~= 0 then
		table.insert(tLabel, "Armor check penalty");
	end

	if bForce and (feat.getValue() or "") ~= "" then
		local sFeat = feat.getValue() or "";
		table.insert(tLabel, string.format("Requires the Force-Sensitive and %s feat", sFeat));
	end

	if type_label then
		type_label.setValue(string.format("[%s]", table.concat(tLabel, "; ")));
	end
end

function onInit()
	self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
end
function update()
	self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
end
function handleActionAdd(sType)
	PowerManagerCore.createPowerAction(self, sType);
end
function onLockModeChanged(bReadOnly)
	if sub_add_buttons then
		sub_add_buttons.setVisible(not bReadOnly);
	end
	if list then
		list.setReadOnly(bReadOnly);
	end
end

buttoncontrol.script:
local _sType;
function setData(sType)
	_sType = sType;
	setIcons("button_action_" .. sType, "button_action_" .. sType .. "_down");
	setTooltipText(Interface.getString("power_menu_action_add_" .. sType));
end
function onButtonPress()
	WindowManager.callOuterWindowFunction(window, "handleActionAdd", _sType);
end

windowclass.script:
function onInit()
	for _,sType in ipairs(PowerActionManagerCore.getSortedActionTypes()) do
		local c = createControl("skill_action_add_button", "actions_iadd_" .. sType);
		c.setData(sType);
	end
end
